fn parse_log_line(l: &str) -> Option<Hit> {
    let l = l.trim_end_matches('\r');
    if l.is_empty() { return None }
    let b = l.find('[')?; let e = l.find("] ")?;
    let ts = &l[b+1..e];
    let (date, time) = parse_ts(ts)?;
    let after = &l[e+2..];
    let q1 = after.find('"')?;
    let ip = l[..b].split_whitespace().next()?.to_string();
    let rest = &after[q1+1..];
    let q2 = rest.rfind('"')?;
    let req = &rest[..q2];
    let tail = &rest[q2+1..];
    let t: Vec<&str> = tail.split_whitespace().collect();
    if t.len() < 3 { return None }
    let status: u32 = t[0].parse().ok()?;
    let bytes: u64 = t[1].parse().ok()?;
    let t2 = &rest[q2+1..];
    let r1 = t2.find('"')?;
    let r2 = t2[r1+1..].find('"')?;
    let referer = t2[r1+1..r1+1+r2].to_string();
    let (method, path) = if req.is_empty() { ("none".to_string(), String::new()) }
        else { let parts: Vec<&str> = req.splitn(3,' ').collect();
               let m = if parts.is_empty() { "none".to_string() } else if KNOWN_METHODS.contains(&parts[0]) { parts[0].to_string() } else { "other".to_string() };
               let p = if parts.len()>1 { parts[1].to_string() } else { String::new() };
               (m,p) };
    Some(Hit{date,time,ip,method,path,status,bytes,referer,raw:l.to_string()})
}
fn parse_ts(ts: &str) -> Option<(String,String)> {
    if let Some(p) = ts.find('T') {
        // ISO 8601
        let d = &ts[..p]; let parts: Vec<&str> = d.split('-').collect();
        if parts.len()!=3 { return None }
        let rest = &ts[p+1..];
        let rest = rest.trim_end_matches('Z');
        let off = rest.find(|c| c=='+' || c=='-');
        let base = match off { Some(i) if i>0 => &rest[..i], _ => rest };
        let tparts: Vec<&str> = base.split(':').collect();
        if tparts.len() < 3 { return None }
        let sec = tparts[2].split('.').next()?;
        let _ = off;
        return Some((format!("{}/{:02}/{:02}", parts[0], parts[1].parse::<u32>().ok()?, parts[2].parse::<u32>().ok()?),
                     format!("{}:{}:{}", tparts[0], tparts[1], sec)));
    }
    // nginx: DD/Mon/YYYY:HH:MM:SS [+-ZZZZ]
    let sp = ts.find(' ');
    let base = match sp { Some(i) => &ts[..i], None => ts };
    let c: Vec<&str> = base.split(|ch| ch=='/'||ch==':').collect();
    if c.len()!=5 { return None }
    let mon = MONTHS.iter().position(|m| *m==c[1])?;
    let _ = sp;
    Some((format!("{}/{:02}/{:02}", c[2], mon+1, c[0].parse::<u32>().ok()?), format!("{}:{}:{}", c[3], c[4].len()==2?c[4]:"00", "00")))
