enum StrNode { Re(regex::Regex), And(Box<StrNode>,Box<StrNode>), Or(Box<StrNode>,Box<StrNode>), Not(Box<StrNode>) }
mod regex {
    // very small regex engine: supports ^, $, ., \d, \w, \s, [..], * + ? {n} (), |, escapes
    #[derive(Clone,Debug)] pub enum N { Empty, Lit(char), Any, Class(Vec<(char,char)>,bool),
        Star(Box<N>), Plus(Box<N>), Opt(Box<N>), Seq(Vec<N>), Alt(Vec<N>) }
    pub struct Regex { pub n: N }
    impl Regex {
        pub fn new(pat: &str) -> Result<Regex, String> {
            let cs: Vec<char> = pat.chars().collect();
            let mut i = 0usize;
            let n = parse_alt(&cs, &mut i)?;
            if i != cs.len() { return Err(format!("unexpected '{}'", cs[i])) }
            Ok(Regex{n})
        }
        pub fn is_match(&self, s: &str) -> bool {
            let cs: Vec<char> = s.chars().collect();
            for start in 0..=cs.len() { if m(&self.n, &cs, start, &mut |_| true) { return true } }
            false
        }
    }
    fn parse_alt(c:&[char], i:&mut usize)->Result<N,String>{
        let mut alts = vec![parse_seq(c,i)?];
        while *i<c.len() && c[*i]=='|' { *i+=1; alts.push(parse_seq(c,i)?); }
        if alts.len()==1 { Ok(alts.pop().unwrap()) } else { Ok(N::Alt(alts)) }
    }
    fn parse_seq(c:&[char], i:&mut usize)->Result<N,String>{
        let mut items=vec![];
        while *i<c.len() && c[*i]!='|' && c[*i]!=')' {
            let a = parse_atom(c,i)?;
            let a = parse_post(c,i,a)?;
            items.push(a);
        }
        if items.is_empty() { Ok(N::Empty) } else if items.len()==1 { Ok(items.pop().unwrap()) } else { Ok(N::Seq(items)) }
    }
    fn parse_post(c:&[char], i:&mut usize, a:N)->Result<N,String>{
        if *i<c.len() { match c[*i] { '*'=>{*i+=1; return Ok(N::Star(Box::new(a)))}, '+'=>{*i+=1; return Ok(N::Plus(Box::new(a)))}, '?'=>{*i+=1; return Ok(N::Opt(Box::new(a)))}, '{'=>{} , _=>{} } }
        Ok(a)
    }
    fn parse_atom(c:&[char], i:&mut usize)->Result<N,String>{
        let ch = c[*i];
        match ch {
            '(' => { *i+=1; let n=parse_alt(c,i)?; if *i>=c.len()||c[*i]!=')' { return Err("unclosed group".into()) } *i+=1; Ok(n) }
            '[' => { *i+=1; let mut neg=false; if *i<c.len()&&c[*i]=='^' { neg=true;*i+=1 }
                     let mut v=vec![]; while *i<c.len() && c[*i]!=']' { if *i+2<c.len() && c[*i+1]=='-' { v.push((c[*i],c[*i+2])); *i+=3 } else { v.push((c[*i],c[*i])); *i+=1 } }
                     if *i>=c.len() { return Err("unclosed character class".into()) } *i+=1; Ok(N::Class(v,neg)) }
            '\\' => { *i+=1; if *i>=c.len(){return Err("trailing backslash".into())} let k=c[*i]; *i+=1;
                      match k { 'd'=>Ok(N::Class(vec![('0','9')],false)), 'w'=>Ok(N::Class(vec![('0','9'),('A','Z'),('_','_'),('a','z')],false)), 's'=>Ok(N::Class(vec![(' ',' '),(9 as char,13 as char)],false)), 'D'=>Ok(N::Class(vec![('0','9')],true)),'W'=>Ok(N::Class(vec![('0','9'),('A','Z'),('_','_'),('a','z')],true)),'S'=>Ok(N::Class(vec![(' ',' '),(9 as char,13 as char)],true)), x=>Ok(N::Lit(x)) } }
