fn build_str_filter(pat:&str)->Result<StrNode,String>{
    let toks = tokenize(pat);
    // recursive: split on top-level '&' and '|'
    fn helper(toks:&[String])->Result<StrNode,String>{
        if toks.is_empty() { return Err(format!("empty")) }
        if toks.len()==1 { let t=&toks[0]; if t=="&"||t=="|" { return Err(InvalidPattern(t.clone(),format!("unexpected '{}'",t))) }
            if t.starts_with('!') { let rest=&t[1..]; return Ok(StrNode::Not(Box::new(helper(&[rest.to_string()])?))) }
            if t.starts_with('(') && t.ends_with(')') && t.len()>2 {
                let inner=&t[1..t.len()-1];
                return Ok(helper(&tokenize(inner))?);
            }
            return Ok(StrNode::Re(regex::Regex::new(t).map_err(|e| InvalidRegex(t.clone(), e))?));
        }
        // find top-level & then |
        let mut depth=0;
        for op in ["&","|"] {
            for i in 0..toks.len() { if toks[i]==op { depth+=1; } }
            if depth>0 {
                let mut parts=vec![]; let mut cur=vec![];
                for t in toks { if t==op { parts.push(cur.clone()); cur=vec![]; } else { cur.push(t.clone()) } }
                parts.push(cur);
                let mut it=parts.into_iter().map(|p| helper(&p));
                let first=it.next().unwrap()?;
                return Ok(if op=="&" { StrNode::And(Box::new(first), Box::new(fold(it)?)) } else { StrNode::Or(Box::new(first), Box::new(fold(it)?)) });
            }
        }
        return helper(&[toks.join(" ")]);
    }
    fn fold(mut it: std::vec::IntoIter<Vec<String>>) -> Result<StrNode,String> {
        let mut acc = it.next().unwrap()?;
        while let Some(p)=it.next() { acc = StrNode::And(Box::new(acc), Box::new(helper(&p)?)); }
        Ok(acc)
    }
    fn InvalidPattern(p:String,e:String)->String{ format!("InvalidPattern({:?}, {:?})",p,e) }
    fn InvalidRegex(p:String,e:String)->String{ format!("InvalidRegex(Syntax(\n~~~\nregex parse error:\n    {}\n    ^\nerror: {}\n~~~\n))", p, e) }
