fn main() {
    let args: Vec<String> = std::env::args().skip(1).collect();
    let mut o = Opts{ files: vec![], key: "hits".into(), level: 1, fields: vec!["date".into(),"status".into(),"ref".into(),"path".into()],
        changes: false, date: None, ip: None, method: None, path: None, referer: None, status: None, time: None,
        all: false, no_name_check: false, output: "tables".into(), silent: false, color: "auto".into() };
    let mut i = 0;
    let mut ver = false; let mut hlp = false;
    while i < args.len() {
        let a = &args[i];
        let (flag, val) = if let Some(r) = a.find('=') { (a[..r].to_string(), Some(a[r+1..].to_string())) } else { (a.clone(), None) };
        let mut next = |i:&mut usize| -> String { let v = if let Some(v)=&val { v.clone() } else { *i+=1; args.get(*i).cloned().unwrap_or_default() }; v };
        match flag.as_str() {
            "--help" => hlp = true,
            "--version" => ver = true,
            "--color" => { o.color = next(&mut i) },
            "-k"|"--key" => { o.key = next(&mut i) },
            "-l"|"--length" => { o.level = next(&mut i).parse().unwrap_or(1) },
            "-f"|"--field"|"--fields" => { o.fields = next(&mut i).split(',').map(|s|s.to_string()).collect() },
            "-c"|"--changes" => { o.changes = true },
            "-d"|"--date" => { o.date = Some(next(&mut i)) },
            "-i"|"--ip" => { o.ip = Some(next(&mut i)) },
            "-m"|"--method" => { o.method = Some(next(&mut i)) },
            "-p"|"--path" => { o.path = Some(next(&mut i)) },
            "-r"|"--referrer"|"--referer" => { o.referer = Some(next(&mut i)) },
            "-s"|"--status" => { o.status = Some(next(&mut i)) },
            "-t"|"--time" => { o.time = Some(next(&mut i)) },
            "-a"|"--all" => { o.all = true },
            "--no-name-check" => { o.no_name_check = true },
            "-o"|"--output" => { o.output = next(&mut i) },
            "--silent-load" => { o.silent = true },
            _ => o.files.push(a.clone()),
        }
        i += 1;
    }
    if ver { println!("rhit 2.0.4"); return }
    if hlp { print!("{}", help()); for (s,l,d) in HELP_ROWS { print!("{}", row(s,l,d)) } print!("{}", HELP_FOOT); return }
    // resolve fields
    let mut fields: Vec<String> = vec![];
    for f in &o.fields {
        match f.as_str() {
            "a"|"all" => fields = vec!["date".into(),"time".into(),"method".into(),"status".into(),"ip".into(),"ref".into(),"path".into()],
            "+" => { for x in ["date","time","method","status","ip","ref","path"] { if !fields.contains(&x.to_string()) { fields.push(x.into()) } } }
            x => { if !fields.contains(&x.to_string()) { fields.push(x.to_string()) } }
        }
    }
    if fields.is_empty() { fields = vec!["date".into(),"status".into(),"ref".into(),"path".into()] }
    let _ = fields;
    println!("rhit 2.0.4");
}

