            let s = d.total.entry(key).or_insert_with(Series::default);
            while s.hits.len() < idx+1 { s.hits.push(0); s.bytes.push(0); }
            s.hits[idx]+=1; s.bytes[idx]+=h.bytes;
        };
        if with_path { bump(self, h.path.clone()); }
        if with_ref  { bump(self, format!("r{}", h.referer)); }
        if with_ip   { bump(self, format!("i{}", h.ip)); }
        bump(self, format!("m{}", h.method));
        bump(self, format!("s{}", h.status));
