                for t in toks { if t==op { parts.push(cur.clone()); cur=vec![]; } else { cur.push(t.clone()) } }
                parts.push(cur);
                let mut it=parts.into_iter().map(|p| helper(&p));
                let first=it.next().unwrap()?;
                return Ok(if op=="&" { StrNode::And(Box::new(first), Box::new(fold(it)?)) } else { StrNode::Or(Box::new(first), Box::new(fold(it)?)) });
            }
        }
        return helper(&[toks.join(" ")]);
    }
    fn fold(mut it: std::vec::IntoIter<Vec<String>>) -> Result<StrNode,String> {
        let mut acc = it.next().unwrap()?;
        while let Some(p)=it.next() { acc = StrNode::And(Box::new(acc), Box::new(helper(&p)?)); }
        Ok(acc)
    }
    fn InvalidPattern(p:String,e:String)->String{ format!("InvalidPattern({:?}, {:?})",p,e) }
    fn InvalidRegex(p:String,e:String)->String{ format!("InvalidRegex(Syntax(\n~~~\nregex parse error:\n    {}\n    ^\nerror: {}\n~~~\n))", p, e) }
    if toks.is_empty() { return Ok(StrNode::Re(regex::Regex::new("$^").unwrap())) }
    let n = helper(&toks)?;
    Ok(n)
}
impl StrNode { fn m(&self,s:&str)->bool{ match self { StrNode::Re(r)=>r.is_match(s), StrNode::And(a,b)=>a.m(s)&&b.m(s), StrNode::Or(a,b)=>a.m(s)||b.m(s), StrNode::Not(a)=>!a.m(s) } } }

struct Opts { files: Vec<String>, key: String, level: usize, fields: Vec<String>, changes: bool,
  date: Option<String>, ip: Option<String>, method: Option<String>, path: Option<String>, referer: Option<String>, status: Option<String>, time: Option<String>,
  all: bool, no_name_check: bool, output: String, silent: bool, color: String }

